mapper.select:
SELECT f.id, f.owner_user_id, f.factory_name, f.factory_address, f.profile_version, f.factory_status, u.user_status AS owner_status, m.id AS merchant_id, m.sub_mchid, m.account_status, m.profit_sharing_status, m.version AS merchant_version FROM factory_profile f JOIN sys_user u ON u.id=f.owner_user_id LEFT JOIN factory_wechat_merchant_account m ON m.factory_id=f.id WHERE f.id IN
#{id}
ORDER BY f.id
